import { writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

const schemaUrl = process.env.API_SCHEMA_URL ?? 'http://localhost:3000/docs-json'
const outputFile = new URL('../src/lib/api-schema.d.ts', import.meta.url)

const header = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 * Run \`npm run gen:api\` to regenerate it.
 */

`

const ast = await openapiTS(new URL(schemaUrl))
await writeFile(outputFile, header + astToString(ast))
console.log(`API schema generated from ${schemaUrl}`)
